/* ==UserStyle==
@name           Pplware, versão limpa
@namespace      USO Archive
@author         ZarkBit
@description    `Página do Pplware mais limpa e sem ads`
@version        20260305.1.0
@license        CC0-1.0
@preprocessor   uso
==/UserStyle== */
@namespace url(http://www.w3.org/1999/xhtml);
@-moz-document domain("pplware.sapo.pt") {
/* === LAYOUT === */
    body {
        padding-top: 0;
    }
    #page {
        background-color: #01265D;
    }
    .content {
        border-right: none;
        width: 100%;
    }
    .content .post,
    .content .page {
        width: unset;
    }
    .col-2cl .main-inner {
        background: none;
        padding-right: 0;
        max-width: 80%;
        margin: auto;
    }
    /* === HEADER === */
    .header-left,
    .header-right {
        max-height: 85px;
    }
    #header .pad {
        padding: 0;
    }
    /* === POST STYLES === */
    .single .post,
    .blog .post,
    .content .post {
        box-shadow: 0 0 5px 1px rgba(0, 0, 0, 0.75);
        border-radius: 0;
        padding: 10px 15px;
    }
    .blog .post {
        padding: 11px 25px 10px 25px;
        max-width: none;
    }
    .entry.excerpt {
        padding: 11px 20px 10px 20px;
    }
    .post-title {
        text-align: center;
    }
    /* === POST LIST === */
@media only screen and (min-width: 720px) {
    .post-list .post-row {
        padding: 0;
        float: none;
        display: flex;
        justify-content: center;
        gap: 10px;
        width: unset;
        margin-right: 0 !important;
        box-sizing: border-box;
        align-items: stretch;
    }
    .post-list .post-row .invisible-mobile {
        width: 45%;
        box-sizing: border-box;
        display: flex;
        flex-direction: column;
    }
    .post-list .post-row .invisible-mobile .post {
        flex: 1;
    }
}
    .post-list .post,
    .post-list .page {
        width: 100%;
        padding: 10px;
        box-sizing: border-box;
    }
    .post-list .post-inner {
        margin-right: 0;
    }
    /* === IMAGES === */
    .home .post-inner img[class*="wp-image-"],
    .archive .post-inner img[class*="wp-image-"]{
        width: 60%;
        margin-left: auto;
        margin-right: auto;
        display: block;
    }
    .article-box-img,
    .entry img.aligncenter,
    .entry img.alignnone {
        width: 55%;
        margin-left: auto;
        margin-right: auto;
        display: block;
    }
    .article-box-img {
        width: 75%;
    }
    /* === COMMENTS === */
    .commentlist .comment-body {
        box-shadow: 0 1px 4px rgba(0, 0, 0, 0.3),
        0 0 40px rgba(0, 0, 0, 0.1) inset;
        border-radius: 0;
        background: #F0F0F0;
        padding: 10px 0 10px 10px;
    }
    /* === MISC === */
    .page-title {
        border-bottom: none;
    }
    .pad {
        padding: 10px 0 0 0;
    }
    .embed-container {
        box-shadow: 0 0 5px 1px rgba(0, 0, 0, 0.75);
    }
        .pdfemb-viewer {
    margin-left: auto !important;
    margin-right: auto !important;
    }
    /* === AD BLOCKING & CLEANUP === */
    .google_news,
    .parceiro_iframe,
    #LeaderboardPos1,
    #LeaderboardPos2,
    #LeaderboardPos3,
    #LeaderboardPos4,
    #LeaderboardPos5,
    #bsu-placeholder,
    #bsu-v2-ctn,
    .header-pub-sapo,
    #top-pub,
    .ban-horizontal-artigo,
    .full-share-box,
    .post-tags,
    .pad.group hr,
    .ppl_lost_posts,
    .col-2cl .s1,
    #footer,
    ul.post-nav.group,
    h4.heading,
    ul.related-posts.group,
    #disclaimer,
    #ebAd60569025_billboard_div_0_60569025_2965759004516435,
    #\#sidepub,
    #taboola-below-article-thumbnails,
    .ob-smartfeed-wrapper,
    .OUTBRAIN,
    [data-widget-id*="AR_"],
    [data-widget-id*="FMS_CP_"],
    .ob-widget,
    .ob-feed-layout,
    [id*="FlooradPos"],
    [data-pub-formatid="Floorad"],
    div[data-pub="appNexus"] {
        display: none !important;
    }
}
